nextflow_process {

    name "Test Process PCNE"
    script "../main.nf"
    process "PCNE"

    tag "modules"
    tag "modules_nfcore"
    tag "pcne"

    test("sarscov2 - bam") {

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                ]
                input[1] = [
                    [ id: 'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id: 'transcriptome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/transcriptome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assert snapshot(
                [
                    log: file(process.out.log[0][1]).name,
                    results: process.out.results,
                    versions: process.out.versions_pcne
                ]
                ).match()

        }

    }

    test("sarscov2 - bam - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                ]
                input[1] = [
                    [ id: 'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id: 'transcriptome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/transcriptome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assert snapshot(sanitizeOutput(process.out)).match()
        }

    }

    test("sarscov2 - bam - plot") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = [
                    [ id:'test', single_end:false ], // meta map
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/illumina/bam/test.paired_end.sorted.bam', checkIfExists: true)
                ]
                input[1] = [
                    [ id: 'genome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                ]
                input[2] = [
                    [ id: 'transcriptome' ],
                    file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/transcriptome.fasta', checkIfExists: true)
                ]
                """
            }
        }

        then {
            assert process.success
            assert process.out.plots.get(0).get(1).endsWith(".png")
            assert snapshot(
                [
                    log: file(process.out.log[0][1]).name,
                    plot: file(process.out.plots[0][1]).name,
                    results: process.out.results,
                    versions: process.out.versions_pcne
                ]
            ).match()
        }

    }
}

